/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #0a0a0a;
  --white: #ffffff;
  --gray-50: #f9f9f9;
  --gray-100: #f2f2f2;
  --gray-200: #e5e5e5;
  --gray-400: #9a9a9a;
  --gray-600: #5a5a5a;
  --gray-800: #2a2a2a;
  --accent: #e63946;
  --accent-dark: #c1121f;
  --gold: #f4a261;
  --radius: 12px;
  --radius-sm: 6px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-hover: 0 12px 40px rgba(0,0,0,0.16);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  color: var(--black);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { display: block; width: 100%; object-fit: cover; }
a { text-decoration: none; color: inherit; }
button { cursor: pointer; border: none; background: none; font-family: var(--font); }

/* ===== TYPOGRAPHY ===== */
.section-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.section-title {
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 800;
  line-height: 1.15;
  color: var(--black);
  margin-top: 0.3rem;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2rem;
  gap: 1rem;
}

.view-all {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: 0.3rem;
  white-space: nowrap;
  transition: color var(--transition);
}
.view-all:hover { color: var(--black); }
.view-all svg { transition: transform var(--transition); }
.view-all:hover svg { transform: translateX(3px); }

/* ===== LAYOUT ===== */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

section { padding: 72px 0; }

/* ===== NAV ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.nav-inner {
  display: flex;
  align-items: center;
  height: 64px;
  gap: 2rem;
}

.nav-logo {
  font-size: 1.3rem;
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--black);
  flex-shrink: 0;
}
.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex;
  gap: 1.75rem;
  list-style: none;
  flex: 1;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: color var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--black); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-left: auto;
}

.nav-icon-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition);
  position: relative;
}
.nav-icon-btn:hover { background: var(--gray-100); }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: var(--accent);
  color: var(--white);
  font-size: 0.6rem;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}

.nav-btn-primary {
  padding: 0 18px;
  height: 38px;
  border-radius: 999px;
  background: var(--black);
  color: var(--white);
  font-size: 0.82rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
}
.nav-btn-primary:hover { background: var(--gray-800); transform: scale(1.02); }

.nav-hamburger { display: none; }

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--black);
  color: var(--white);
  text-align: center;
  padding: 10px 24px;
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.announcement-bar a { color: var(--gold); text-decoration: underline; text-underline-offset: 2px; }

/* ===== HERO ===== */
.hero {
  padding: 0;
  min-height: calc(100vh - 64px);
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.hero-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 80px 60px 80px 0;
  padding-left: 0;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff3f4;
  border: 1px solid #ffd0d3;
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 999px;
  margin-bottom: 1.5rem;
  width: fit-content;
}

.hero-title {
  font-size: clamp(2.8rem, 5vw, 4.2rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: 1.25rem;
}
.hero-title em { font-style: normal; color: var(--accent); }

.hero-subtitle {
  font-size: 1.05rem;
  color: var(--gray-600);
  max-width: 420px;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}

.btn-primary {
  padding: 14px 32px;
  border-radius: 999px;
  background: var(--black);
  color: var(--white);
  font-size: 0.92rem;
  font-weight: 700;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  display: inline-flex; align-items: center; gap: 8px;
}
.btn-primary:hover { background: var(--accent); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(230,57,70,0.3); }

.btn-secondary {
  padding: 14px 28px;
  border-radius: 999px;
  border: 2px solid var(--gray-200);
  color: var(--black);
  font-size: 0.92rem;
  font-weight: 600;
  transition: border-color var(--transition), background var(--transition);
  display: inline-flex; align-items: center; gap: 8px;
}
.btn-secondary:hover { border-color: var(--black); background: var(--gray-50); }

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--gray-200);
}

.hero-stat-value {
  font-size: 1.6rem;
  font-weight: 900;
  letter-spacing: -0.03em;
}
.hero-stat-label {
  font-size: 0.78rem;
  color: var(--gray-400);
  font-weight: 500;
  margin-top: 2px;
}

.hero-visual {
  position: relative;
  overflow: hidden;
  background: var(--gray-100);
}

.hero-img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.8s ease;
}
.hero-visual:hover .hero-img { transform: scale(1.03); }

.hero-badge {
  position: absolute;
  bottom: 32px;
  left: 32px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: var(--shadow);
  animation: floatUp 0.6s ease 0.4s both;
}
@keyframes floatUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

.hero-badge-icon {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: #fff3f4;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
}
.hero-badge-title { font-size: 0.82rem; font-weight: 700; }
.hero-badge-sub { font-size: 0.72rem; color: var(--gray-400); }

/* ===== BRANDS STRIP ===== */
.brands-strip {
  padding: 32px 0;
  border-top: 1px solid var(--gray-200);
  border-bottom: 1px solid var(--gray-200);
}

.brands-inner {
  display: flex;
  align-items: center;
  gap: 3rem;
  overflow: hidden;
}

.brands-label {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-400);
  white-space: nowrap;
  flex-shrink: 0;
}

.brands-logos {
  display: flex;
  gap: 3rem;
  align-items: center;
  flex: 1;
  overflow: hidden;
}

.brand-logo {
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--gray-400);
  white-space: nowrap;
  transition: color var(--transition);
}
.brand-logo:hover { color: var(--black); }

/* ===== FEATURED PRODUCTS ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--white);
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
  position: relative;
}
.product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-hover); }

.product-img-wrap {
  position: relative;
  overflow: hidden;
  background: var(--gray-100);
  aspect-ratio: 3/4;
}

.product-img-wrap img {
  transition: transform 0.5s ease;
  height: 100%;
}
.product-card:hover .product-img-wrap img { transform: scale(1.07); }

.product-badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.badge {
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.badge-new { background: var(--black); color: var(--white); }
.badge-sale { background: var(--accent); color: var(--white); }
.badge-hot { background: var(--gold); color: var(--black); }
.badge-sold { background: var(--gray-400); color: var(--white); }

.product-quick-add {
  position: absolute;
  bottom: 12px;
  left: 12px; right: 12px;
  background: var(--white);
  color: var(--black);
  border-radius: 999px;
  padding: 10px;
  font-size: 0.8rem;
  font-weight: 700;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity var(--transition), transform var(--transition);
}
.product-card:hover .product-quick-add { opacity: 1; transform: translateY(0); }
.product-quick-add:hover { background: var(--black); color: var(--white); }

.product-wishlist {
  position: absolute;
  top: 12px; right: 12px;
  width: 34px; height: 34px;
  border-radius: 50%;
  background: var(--white);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  opacity: 0;
  transform: scale(0.8);
  transition: opacity var(--transition), transform var(--transition);
  font-size: 0.9rem;
}
.product-card:hover .product-wishlist { opacity: 1; transform: scale(1); }
.product-wishlist.active { color: var(--accent); }
.product-wishlist:hover { background: var(--gray-100); }

.product-info { padding: 14px 4px 8px; }

.product-category {
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: 4px;
}

.product-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--black);
  margin-bottom: 6px;
  line-height: 1.3;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 8px;
}
.stars { color: var(--gold); font-size: 0.75rem; letter-spacing: 1px; }
.rating-count { font-size: 0.72rem; color: var(--gray-400); }

.product-price {
  display: flex;
  align-items: center;
  gap: 8px;
}
.price-current { font-size: 1rem; font-weight: 800; }
.price-original { font-size: 0.85rem; color: var(--gray-400); text-decoration: line-through; }
.price-discount { font-size: 0.72rem; font-weight: 700; color: var(--accent); }

/* ===== DEALS SECTION ===== */
.deals { background: var(--gray-50); }

.deals-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 20px;
  align-items: start;
}

.deal-card {
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  cursor: pointer;
}

.deal-card-main {
  grid-row: span 2;
  background: var(--black);
  color: var(--white);
}

.deal-img-wrap {
  position: relative;
  overflow: hidden;
}

.deal-card-main .deal-img-wrap { aspect-ratio: 2/3; }
.deal-card-sm .deal-img-wrap { aspect-ratio: 16/9; }

.deal-img-wrap img { transition: transform 0.6s ease; }
.deal-card:hover .deal-img-wrap img { transform: scale(1.05); }

.deal-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, transparent 55%);
}

.deal-content {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 24px;
  color: var(--white);
}

.deal-tag {
  display: inline-block;
  background: var(--accent);
  color: var(--white);
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.deal-title { font-size: 1.2rem; font-weight: 800; line-height: 1.2; margin-bottom: 6px; }
.deal-card-main .deal-title { font-size: 1.6rem; }

.deal-price-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 8px;
}
.deal-price { font-size: 1.1rem; font-weight: 800; }
.deal-original { font-size: 0.85rem; opacity: 0.6; text-decoration: line-through; }

.deal-timer {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}
.timer-block {
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(4px);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  text-align: center;
  min-width: 44px;
}
.timer-num { font-size: 1.1rem; font-weight: 800; display: block; }
.timer-label { font-size: 0.6rem; opacity: 0.7; text-transform: uppercase; letter-spacing: 0.05em; }

.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
  background: var(--white);
  color: var(--black);
  font-size: 0.82rem;
  font-weight: 700;
  padding: 9px 18px;
  border-radius: 999px;
  transition: background var(--transition), color var(--transition);
}
.deal-cta:hover { background: var(--accent); color: var(--white); }

.deal-card-sm .deal-content { padding: 16px 18px; }
.deal-card-sm .deal-title { font-size: 1rem; }

/* ===== CATEGORIES ===== */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}

.category-card {
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  background: var(--gray-100);
  aspect-ratio: 3/4;
  display: flex; flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  padding: 14px;
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
}
.category-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }

.category-card img {
  position: absolute;
  inset: 0;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.category-card:hover img { transform: scale(1.08); }

.category-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.55) 0%, transparent 60%);
}

.category-label {
  position: relative;
  z-index: 1;
  color: var(--white);
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1.2;
}

/* ===== EDITORIAL ===== */
.editorial { background: var(--white); }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 24px;
}

.editorial-card {
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  background: var(--gray-100);
  position: relative;
  transition: box-shadow var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-hover); }

.editorial-card-featured { display: flex; flex-direction: column; }

.editorial-img-wrap {
  overflow: hidden;
  position: relative;
}
.editorial-card-featured .editorial-img-wrap { aspect-ratio: 16/9; }
.editorial-card-sm .editorial-img-wrap { aspect-ratio: 16/9; height: 180px; }

.editorial-img-wrap img { transition: transform 0.6s ease; }
.editorial-card:hover .editorial-img-wrap img { transform: scale(1.05); }

.editorial-body {
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.editorial-tag {
  background: #fff3f4;
  color: var(--accent);
  font-size: 0.68rem;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.editorial-date { font-size: 0.75rem; color: var(--gray-400); }

.editorial-title {
  font-size: 1.15rem;
  font-weight: 800;
  line-height: 1.3;
  margin-bottom: 10px;
}
.editorial-card-featured .editorial-title { font-size: 1.35rem; }

.editorial-excerpt {
  font-size: 0.875rem;
  color: var(--gray-600);
  line-height: 1.65;
  margin-bottom: 16px;
  flex: 1;
}

.editorial-author {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
}
.author-avatar {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--gray-600);
  overflow: hidden;
  flex-shrink: 0;
}
.author-name { font-size: 0.8rem; font-weight: 600; }
.author-role { font-size: 0.7rem; color: var(--gray-400); }

.editorial-side {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.editorial-card-sm {
  display: flex;
  flex-direction: row;
  height: 130px;
}
.editorial-card-sm .editorial-img-wrap {
  width: 140px;
  flex-shrink: 0;
  height: 100%;
  aspect-ratio: auto;
}
.editorial-card-sm .editorial-img-wrap img { height: 100%; }
.editorial-card-sm .editorial-body { padding: 16px 18px; }
.editorial-card-sm .editorial-title { font-size: 0.9rem; margin-bottom: 6px; }
.editorial-card-sm .editorial-excerpt { font-size: 0.78rem; -webkit-line-clamp: 2; display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 0; }

/* ===== PROMO BANNER ===== */
.promo-banner {
  padding: 0;
  background: var(--black);
}

.promo-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 320px;
}

.promo-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 60px;
  color: var(--white);
}

.promo-eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 1rem;
}

.promo-title {
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
}

.promo-text {
  font-size: 0.95rem;
  opacity: 0.7;
  max-width: 400px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.promo-visual {
  position: relative;
  overflow: hidden;
}
.promo-visual img { height: 100%; object-fit: cover; }

/* ===== NEWSLETTER ===== */
.newsletter { background: var(--gray-50); text-align: center; }

.newsletter-inner { max-width: 540px; margin: 0 auto; }

.newsletter-title { font-size: clamp(1.4rem, 2.5vw, 1.9rem); font-weight: 800; margin-bottom: 0.6rem; }
.newsletter-sub { font-size: 0.9rem; color: var(--gray-600); margin-bottom: 1.75rem; }

.newsletter-form {
  display: flex;
  gap: 10px;
  max-width: 440px;
  margin: 0 auto 1rem;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 18px;
  border: 2px solid var(--gray-200);
  border-radius: 999px;
  font-size: 0.9rem;
  font-family: var(--font);
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input:focus { border-color: var(--black); }

.newsletter-form button {
  padding: 14px 24px;
  border-radius: 999px;
  background: var(--black);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--accent); }

.newsletter-note { font-size: 0.75rem; color: var(--gray-400); }

/* ===== FOOTER ===== */
.footer {
  background: var(--black);
  color: rgba(255,255,255,0.7);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 48px;
}

.footer-brand { max-width: 280px; }
.footer-logo { font-size: 1.3rem; font-weight: 900; color: var(--white); letter-spacing: -0.03em; margin-bottom: 1rem; }
.footer-logo span { color: var(--accent); }
.footer-desc { font-size: 0.85rem; line-height: 1.7; margin-bottom: 1.5rem; }

.footer-socials { display: flex; gap: 10px; }
.social-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.15);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.85rem;
  transition: background var(--transition), border-color var(--transition);
  color: var(--white);
}
.social-btn:hover { background: var(--accent); border-color: var(--accent); }

.footer-col-title {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--white);
  margin-bottom: 1.2rem;
}

.footer-links { list-style: none; display: flex; flex-direction: column; gap: 0.7rem; }
.footer-links a { font-size: 0.85rem; transition: color var(--transition); }
.footer-links a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom-text { font-size: 0.8rem; }

.footer-payment {
  display: flex;
  gap: 8px;
  align-items: center;
}

.pay-badge {
  background: rgba(255,255,255,0.08);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 0.7rem;
  font-weight: 700;
  color: rgba(255,255,255,0.7);
}

/* ===== CART SIDEBAR ===== */
.cart-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 200;
  opacity: 0; pointer-events: none;
  transition: opacity var(--transition);
}
.cart-overlay.open { opacity: 1; pointer-events: all; }

.cart-sidebar {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: 400px;
  max-width: 100vw;
  background: var(--white);
  z-index: 201;
  transform: translateX(100%);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex; flex-direction: column;
}
.cart-sidebar.open { transform: translateX(0); }

.cart-header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--gray-200);
  display: flex; align-items: center; justify-content: space-between;
}
.cart-header h3 { font-size: 1rem; font-weight: 800; }
.cart-close {
  width: 34px; height: 34px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition);
  font-size: 1.1rem;
}
.cart-close:hover { background: var(--gray-100); }

.cart-items { flex: 1; overflow-y: auto; padding: 16px 24px; }

.cart-item {
  display: flex;
  gap: 14px;
  padding: 14px 0;
  border-bottom: 1px solid var(--gray-100);
}
.cart-item-img {
  width: 70px; height: 85px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--gray-100);
  flex-shrink: 0;
}
.cart-item-img img { height: 100%; }
.cart-item-info { flex: 1; }
.cart-item-cat { font-size: 0.68rem; color: var(--gray-400); text-transform: uppercase; letter-spacing: 0.06em; }
.cart-item-name { font-size: 0.88rem; font-weight: 700; margin: 2px 0 6px; line-height: 1.3; }
.cart-item-price { font-size: 0.92rem; font-weight: 800; }
.cart-item-qty {
  display: flex; align-items: center; gap: 10px;
  margin-top: 8px;
}
.qty-btn {
  width: 26px; height: 26px;
  border-radius: 50%;
  border: 1px solid var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.9rem;
  transition: background var(--transition);
}
.qty-btn:hover { background: var(--gray-100); }
.qty-num { font-size: 0.85rem; font-weight: 700; min-width: 20px; text-align: center; }
.cart-item-remove { color: var(--gray-400); font-size: 0.75rem; text-decoration: underline; cursor: pointer; margin-top: 4px; display: block; }
.cart-item-remove:hover { color: var(--accent); }

.cart-footer {
  padding: 20px 24px;
  border-top: 1px solid var(--gray-200);
}
.cart-summary { margin-bottom: 16px; }
.cart-row { display: flex; justify-content: space-between; font-size: 0.88rem; color: var(--gray-600); margin-bottom: 6px; }
.cart-total { font-size: 1.05rem; font-weight: 800; color: var(--black); }
.cart-checkout-btn {
  width: 100%;
  padding: 16px;
  border-radius: 999px;
  background: var(--black);
  color: var(--white);
  font-size: 0.95rem;
  font-weight: 700;
  transition: background var(--transition);
  margin-bottom: 10px;
}
.cart-checkout-btn:hover { background: var(--accent); }
.cart-continue { display: block; text-align: center; font-size: 0.82rem; color: var(--gray-400); text-decoration: underline; cursor: pointer; }
.cart-continue:hover { color: var(--black); }

/* ===== TOAST ===== */
.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(80px);
  background: var(--black);
  color: var(--white);
  padding: 12px 24px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  z-index: 300;
  display: flex; align-items: center; gap: 8px;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  white-space: nowrap;
}
.toast.show { transform: translateX(-50%) translateY(0); }

/* ===== SCROLL ANIMATIONS ===== */
.fade-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.fade-in.visible { opacity: 1; transform: translateY(0); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1100px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; min-height: auto; }
  .hero-content { padding: 60px 0 40px; }
  .hero-visual { height: 420px; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card-main { grid-column: span 2; grid-row: span 1; }
  .deal-card-main .deal-img-wrap { aspect-ratio: 16/7; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card-sm { flex-direction: column; height: auto; }
  .editorial-card-sm .editorial-img-wrap { width: 100%; height: 160px; }
  .promo-inner { grid-template-columns: 1fr; }
  .promo-visual { height: 240px; }
}

@media (max-width: 680px) {
  section { padding: 48px 0; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .categories-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card-main { grid-column: span 1; }
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }
  .footer-grid { grid-template-columns: 1fr; }
  .promo-content { padding: 40px 24px; }
}

