    if (el("timer-h")) el("timer-h").textContent = h;
    if (el("timer-m")) el("timer-m").textContent = m;
    if (el("timer-s")) el("timer-s").textContent = s;
  }
  tick();
  setInterval(tick, 1000);
}

// ===== TOAST =====
let toastTimeout;
function showToast(msg) {
  const toast = $("#toast");
  if (!toast) return;
  toast.querySelector(".toast-msg").textContent = msg;
  toast.classList.add("show");
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove("show"), 2800);
}

// ===== NEWSLETTER =====
function initNewsletter() {
  const form = $("#newsletter-form");
  if (!form) return;
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const input = form.querySelector("input");
    if (!input.value) return;
    showToast("🎉 You're subscribed! Check your inbox.");
    input.value = "";
  });
}

// ===== SCROLL ANIMATIONS =====
function observeFadeIns() {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        setTimeout(() => entry.target.classList.add("visible"), i * 60);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1, rootMargin: "0px 0px -40px 0px" });

  $$(".fade-in").forEach(el => observer.observe(el));
}

// ===== STICKY NAV SHADOW =====
function initNavScroll() {
  const nav = $(".nav");
  window.addEventListener("scroll", () => {
    nav.style.boxShadow = window.scrollY > 10 ? "0 2px 20px rgba(0,0,0,0.08)" : "none";
  }, { passive: true });
}

// ===== INIT =====
document.addEventListener("DOMContentLoaded", () => {
  renderProducts();
  renderCart();
  initTimer();
  initNewsletter();
  initNavScroll();
  observeFadeIns();

  // Cart open/close
  $$(".open-cart-btn").forEach(btn => btn.addEventListener("click", openCart));
  $("#cart-overlay")?.addEventListener("click", closeCart);
  $("#cart-close-btn")?.addEventListener("click", closeCart);
  $("#cart-continue")?.addEventListener("click", closeCart);

  // Keyboard close
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeCart();
  });

  // Checkout placeholder
  $("#cart-checkout-btn")?.addEventListener("click", () => {
    if (cart.length === 0) { showToast("Your cart is empty"); return; }
    showToast("🎉 Proceeding to checkout...");
  });
});
